import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Create your first project","description":"","frontmatter":{"title":"Create your first project"},"headers":[],"relativePath":"docs/getting-started/create-first-project.md","filePath":"docs/getting-started/create-first-project.md","lastUpdated":1794290851000}'),s={name:"docs/getting-started/create-first-project.md"};function n(i,e,c,d,p,l){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="create-your-first-project" tabindex="-1">Create your first project <a class="header-anchor" href="#create-your-first-project" aria-label="Permalink to &quot;Create your first project&quot;">​</a></h1><p>A <strong>project</strong> keeps related documents, data and chat together. Start from <strong>Add Project</strong> on the Dashboard. Give it a name and choose its kind, or use <strong>Auto Detect</strong> to choose from the statements you add.</p><h2 id="pick-a-kind-of-project" tabindex="-1">Pick a kind of project <a class="header-anchor" href="#pick-a-kind-of-project" aria-label="Permalink to &quot;Pick a kind of project&quot;">​</a></h2><ul><li><strong>Banking + Credit Cards</strong> — bank and credit-card activity, spending and income.</li><li><strong>Investment</strong> — brokerage holdings, transactions and performance.</li><li><strong>Assets / Liabilities</strong> — property, other assets and debts entered or linked to your records.</li><li><strong>Retail Purchases</strong> — supported retailer order histories, currently Amazon.</li><li><strong>General Documents</strong> — personal documents to search, summarize and discuss with AI, including tax and trust documents.</li></ul><p>You can create an empty project first. <strong>Add statements now (optional)</strong> lets you import files during creation instead; otherwise add them later from the project.</p><h2 id="try-example-data" tabindex="-1">Try example data <a class="header-anchor" href="#try-example-data" aria-label="Permalink to &quot;Try example data&quot;">​</a></h2><p>Banking, investment and retail projects offer example data. Use it to try <a href="/docs/getting-started/browse-recipes">recipes</a> and <a href="/docs/getting-started/ask-questions">chat</a>. These projects are labeled as examples and stay separate from your own records.</p><h2 id="connect-projects-later" tabindex="-1">Connect projects later <a class="header-anchor" href="#connect-projects-later" aria-label="Permalink to &quot;Connect projects later&quot;">​</a></h2><p>A combined financial view is a <strong>workbook</strong>, not another statement-import project. After creating your source projects, choose <strong>New Workbook</strong> to connect them. See <a href="/docs/concepts/workbooks">Workbooks</a>.</p><h2 id="next-step" tabindex="-1">Next step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next step&quot;">​</a></h2><p><a href="/docs/getting-started/add-first-source">Add your first source</a>, or explore the example household first.</p>',11)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
